const items = $input.all();
const results = [];

for (const item of items) {
  const payload = item.json.body || item.json || {};
  const hasExplicitSessions = Array.isArray(payload.sessions) && payload.sessions.length > 0;
  const hasExplicitData = Boolean(payload.data && (Array.isArray(payload.data) || payload.data.session_id));
  const isScheduled = !hasExplicitSessions && !hasExplicitData;

  results.push({
    json: {
      ...payload,
      isScheduled,
      tenantId: payload.tenantId || $env.DEFAULT_TENANT_ID || 'demo'
    }
  });
}

return results;

const items = $input.all();
const results = [];
const now = new Date();

for (const item of items) {
  const payload = item.json.body || item.json || {};
  let rawSessions = [];

  if (Array.isArray(payload.sessions)) {
    rawSessions = payload.sessions;
  } else if (Array.isArray(payload.data)) {
    rawSessions = payload.data;
  } else if (payload.data?.schedules && Array.isArray(payload.data.schedules)) {
    rawSessions = payload.data.schedules;
  } else if (payload.schedules && Array.isArray(payload.schedules)) {
    rawSessions = payload.schedules;
  } else if (payload.session_id || payload.id) {
    rawSessions = [payload];
  }

  for (const sess of rawSessions) {
    if (!sess) continue;

    // Calculate time window if session start time is available
    let reminderType = sess.reminder_type || '1h';
    if (sess.start_time || sess.startTime) {
      const sessionStart = new Date(sess.start_time || sess.startTime);
      const diffHours = (sessionStart.getTime() - now.getTime()) / (1000 * 60 * 60);
      if (diffHours >= 11 && diffHours <= 13) {
        reminderType = '12h';
      } else if (diffHours >= 0.5 && diffHours <= 1.5) {
        reminderType = '1h';
      }
    }

    const memberName = sess.member_name || sess.memberName || 'Valued Member';
    const className = sess.class_name || sess.className || 'Studio Class';
    const date = sess.date || sess.sessionDate || new Date().toISOString().split('T')[0];
    const time = sess.time || sess.startTime || '10:00 AM';
    const trainerName = sess.trainer_name || sess.instructor || 'Lead Instructor';
    const location = sess.location || sess.room || 'Main Studio';
    const phone = sess.phone || sess.to || '+910000000000';
    const sessionId = sess.session_id || sess.sessionId || sess.id || `sess_${Date.now()}`;
    const memberId = sess.member_id || sess.memberId || `mem_${Date.now()}`;

    results.push({
      json: {
        to: phone,
        phone,
        template: 'class-reminder',
        template_name: 'class-reminder',
        tenantId: payload.tenantId || sess.tenantId || 'default-tenant',
        eventId: `rem_${sessionId}_${memberId}_${reminderType}`,
        correlationId: `corr_${Date.now()}`,
        idempotencyKey: `class_reminder_${sessionId}_${memberId}_${reminderType}`,
        isDirectDelivery: true,
        source: 'domain_workflow',
        workflow_name: 'class-reminders',
        data: {
          member_name: memberName,
          class_name: className,
          date,
          time,
          trainer_name: trainerName,
          location,
          reminder_window: reminderType
        }
      }
    });
  }
}

return results.length > 0 ? results : [{
  json: {
    processed: 0,
    message: 'No eligible upcoming sessions found in current reminder window.'
  }
}];

